"use client";

import {
  DrawUnderlineLink,
  type DrawUnderlineLinkProps,
} from "@/components/sora-ui/texts/draw-underline-link";

export default function DrawUnderlineLinkCatalogDemo({
  label = "Hover me",
  variant = "default",
  duration = 0.5,
  underlineColor = "#ff4c24",
  ...props
}: DrawUnderlineLinkProps) {
  return (
    <div className="w-full">
      <section className="flex min-h-[100vh] items-center justify-center">
        <DrawUnderlineLink
          duration={duration}
          href="#"
          label={label}
          underlineColor={underlineColor}
          variant={variant}
          {...props}
        />
      </section>
      <section className="flex min-h-[100vh] items-center justify-center">
        <DrawUnderlineLink
          duration={duration}
          href="#"
          label="Keep scrolling"
          underlineColor={underlineColor}
          variant={variant}
          {...props}
        />
      </section>
    </div>
  );
}
